from lib import *
R=[]
R.append((3465396,"बटरनट स्क्वैश और छोले की करी","फ़ाइबर से भरपूर, पेट भरने वाली शाकाहारी करी जो प्रोटीन, पोटैशियम, फ़ॉस्फ़ेट और नमक में कम है। प्रोटीन घटा रहे लोगों के लिए एकदम सही।","4",None,
["1 बड़ा चम्मच जैतून का तेल","1 बटरनट स्क्वैश (लगभग 400g)","1 लाल प्याज़","2 छोटे चम्मच हल्का करी पेस्ट","300ml कम नमक वाला सब्ज़ी स्टॉक","400g कटे हुए टमाटर","400g डिब्बाबंद छोले","3 बड़े चम्मच वसा-रहित ग्रीक योगर्ट","160g कच्चे चावल","30g ताज़ा धनिया","4 साबुत गेहूँ की चपाती"],
["बटरनट स्क्वैश को छीलें, बीज निकालें और टुकड़ों में काटें। एक बड़े फ्राइंग पैन में तेल गरम करें और बटरनट स्क्वैश को 2-3 मिनट हल्का भूरा होने तक पकाएँ। प्याज़ को काटकर करी पेस्ट के साथ पैन में डालें और 3-4 मिनट और भूनें।","स्टॉक डालें, फिर ढककर 15-20 मिनट या स्क्वैश के नरम होने तक धीमी आँच पर पकाएँ। छोले का पानी निथारकर धो लें, फिर टमाटर के साथ करी में डालें। टमाटर के थोड़ा नरम होने तक 3-4 मिनट धीरे-धीरे पकाएँ।","एक सॉसपैन में पानी उबालें। चावल धोकर उबलते पानी में डालें। ढककर आँच को धीमा करें और 20 मिनट या पकने तक पकाएँ।","करी को आँच से उतारें और योगर्ट तथा कटा हुआ धनिया मिलाएँ। चाहें तो पके हुए चावल और एक साबुत गेहूँ की चपाती के साथ परोसें।"],
[[CH,"यह झटपट और आसान सब्ज़ी की करी सप्ताह के बीच के दिनों के लिए एक स्वादिष्ट विकल्प है। वीगन भोजन के लिए पौधे-आधारित योगर्ट या नारियल क्रीम का उपयोग करें।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट का मुख्य स्रोत चावल और चपाती हैं। इस व्यंजन का कार्बोहाइड्रेट मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है। यदि चपाती के बिना परोस रहे हैं, तो आप प्रति परोसे कच्चे चावल की मात्रा 40g से बढ़ाकर 60g कर सकते हैं।"],[PP,"हालाँकि इस व्यंजन में डिब्बाबंद टमाटर और बटरनट स्क्वैश जैसी कुछ उच्च पोटैशियम वाली सामग्री हैं, रेसिपी में उपयोग की गई मात्रा न्यूनतम रखी गई है ताकि पूरा भोजन पोटैशियम में कम रहे और इसलिए पोटैशियम प्रतिबंध का पालन करते हुए भी इसका आनंद लिया जा सके।\nकुल मिलाकर, यह व्यंजन फ़ॉस्फ़ेट में कम है, लेकिन यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"यह व्यंजन प्रति परोसे अपेक्षाकृत कम प्रोटीन वाला है और इसलिए उपयुक्त है यदि आपको कम प्रोटीन वाला आहार लेने की सलाह दी गई है। यदि आपको उच्च प्रोटीन वाला आहार लेने की सलाह दी गई है और आप मांस खाते हैं, तो आप इसे 170g चिकन के साथ परोस सकते हैं। इसे टुकड़ों में काटकर चरण 2 में डाला जा सकता है।"],[GF,"चावल के साथ परोसने पर यह रेसिपी ग्लूटेन-मुक्त है।"],[VG,"पौधे-आधारित योगर्ट या नारियल क्रीम का उपयोग करें।"],[HO,"इस व्यंजन का स्वाद सारे करी पेस्ट और जड़ी-बूटियों से आता है, इसलिए अतिरिक्त नमक की आवश्यकता नहीं है। स्टॉक में कुछ नमक होगा, लेकिन कम या बहुत कम नमक वाले स्टॉक क्यूब या स्टॉक पॉट सुपरमार्केट में आसानी से उपलब्ध हैं।"],[CO,"यह व्यंजन अपेक्षाकृत सस्ता है। काम आसान बनाने के लिए, पहले से तैयार या जमा हुआ बटरनट स्क्वैश उपयोग करके देखें जो पहले से छिला और कटा हुआ होता है!"],[ST,"यदि सारी करी तुरंत नहीं खा रहे हैं, तो योगर्ट डालने से पहले उसे अलग कर लें। ठंडा होने दें, हवाबंद डिब्बे में रखें, फ्रिज में रखें और दो दिन के भीतर खा लें। परोसने से पहले दोबारा गरम करें और योगर्ट मिलाएँ। यदि करी को फ़्रीज़ कर रहे हैं, तो इसे हिस्सों में सीलबंद डिब्बे में रखें। अच्छी तरह पिघलाएँ और दोबारा गरम करें, परोसने से पहले योगर्ट मिलाएँ। चावल को गरम परोसा जाना चाहिए और पहली बार पकाने के तुरंत बाद खा लेना चाहिए, इसे रखकर दोबारा गरम न करें। ताज़े पके चावल के साथ परोसें।"]],
[]))
R.append((3501639,"चिकन और सब्ज़ियों का क्रम्बल","थोड़े से परमेसन और मेवों के साथ एक पौष्टिक भोजन, जो प्रति परोसे बहुत अधिक फ़ॉस्फ़ेट के बिना कुरकुरापन देता है। सब्ज़ियों को पहले उबालने से पोटैशियम की मात्रा कम रहती है।","6",None,
["2 शकरकंद (लगभग 120g), छिले और टुकड़ों में कटे हुए","300g सेलेरियक, छिला और टुकड़ों में कटा हुआ","2 गाजर (लगभग 120g), छिली और टुकड़ों में कटी हुई","1 लीक (लगभग 70g), कटा हुआ","150g जमे हुए मटर","1 छोटा चम्मच जैतून का तेल","400g बिना त्वचा के चिकन ब्रेस्ट, टुकड़ों में कटा हुआ","400ml कम नमक वाला सब्ज़ी स्टॉक","200ml हाफ़-फ़ैट क्रेम फ्रेश","2 बड़े चम्मच सादा मैदा","1 बड़ा चम्मच साबुत दाने वाली सरसों","1 छोटा चम्मच सूखा सेज",["क्रम्बल टॉपिंग","150g बिना नमक का मक्खन"],["क्रम्बल टॉपिंग","200g सादा मैदा"],["क्रम्बल टॉपिंग","25g पिसे हुए बादाम"],["क्रम्बल टॉपिंग","40g परमेसन चीज़, कद्दूकस किया हुआ"],["क्रम्बल टॉपिंग","25g बादाम के फ़्लेक्स"]],
["ओवन को 190°C / फ़ैन 170°C / गैस मार्क 5 पर गरम करें और एक बड़े सॉसपैन में पानी उबालें। सेलेरियक, शकरकंद और गाजर को छीलकर टुकड़ों में काटें। लीक को छाँटकर, साफ़ करके काटें। चिकन को बराबर आकार के टुकड़ों में काटें।","शकरकंद और सब्ज़ियों को उबलते पानी के सॉसपैन में डालें। 10-15 मिनट उबालें, पानी निथारें और फेंक दें। एक फ्राइंग पैन में जैतून का तेल गरम करें और चिकन को पकने तक तलें।","पानी निथारी हुई सब्ज़ियों को चिकन में डालें और सब्ज़ी का स्टॉक मिलाएँ। धीमी आँच पर 5 मिनट पकाएँ।","क्रेम फ्रेश को मैदे और सरसों के साथ मिलाएँ। इसे चिकन और सब्ज़ियों में गाढ़ा होने तक मिलाएँ, फिर सेज डालें। आँच से उतारें।","क्रम्बल के लिए, उँगलियों के सिरों से मक्खन, मैदा और पिसे बादाम को तब तक मसलकर मिलाएँ जब तक वे ब्रेड क्रम्ब्स जैसे न दिखने लगें। परमेसन को कद्दूकस करके मिलाएँ और बादाम के फ़्लेक्स डालें।","चिकन और सब्ज़ियों का भरावन ओवन-सेफ़ डिश में चम्मच से डालें और ऊपर क्रम्बल बिखेरें। पकाने के लिए, ऊपर से सुनहरा भूरा होने तक 30-35 मिनट ओवन में बेक करें।"],
[[CH,"यह नमकीन क्रम्बल मलाईदार चिकन और सब्ज़ियों के भरावन और कुरकुरी, चीज़ वाली परत के साथ स्वादिष्ट है। परिवार के भोजन के लिए बढ़िया और घर पर फ़्रीज़ करने के लिए उपयुक्त।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट मुख्य रूप से शकरकंद और मैदे से आता है। कार्बोहाइड्रेट के मान उन लोगों के लिए दिए गए हैं जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"मेवों में फ़ॉस्फ़ेट और पोटैशियम दोनों अधिक होते हैं, लेकिन यहाँ उपयोग की गई मात्रा में कुरकुरी क्रम्बल परत के लिए बादाम शामिल किए जा सकते हैं। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें। सब्ज़ियों को उबालने और पानी फेंकने से कुछ पोटैशियम निकालने में मदद मिलती है। सेलेरियक से अक्सर इसके उच्च पोटैशियम के कारण परहेज़ किया जाता है, लेकिन उबालने और दी गई मात्रा में उपयोग करने पर इसे कम पोटैशियम वाले आहार में शामिल किया जा सकता है।"],[PR,"इस व्यंजन में चिकन प्रोटीन देता है और यदि आप डायलिसिस पर हैं तो यह एक अच्छा विकल्प है। जिन लोगों को प्रोटीन का सेवन घटाने की सलाह दी गई है, वे सब्ज़ियों के क्रम्बल की रेसिपी क्यों न आज़माएँ।"],[GF,"क्रम्बल में ग्लूटेन-मुक्त आटे और सॉस में कॉर्नफ़्लोर का उपयोग करें।"],[HO,"इस रेसिपी में कोई अतिरिक्त नमक नहीं है लेकिन यह कम नमक वाले व्यंजन की श्रेणी की सीमा से थोड़ा ऊपर है। इस व्यंजन में वसा की मात्रा कम करने के लिए मक्खन की जगह कम वसा वाले मार्जरीन का उपयोग करें।"],[ST,"इस रेसिपी को ओवन में बेक करने से पहले क्लिंग फ़िल्म और फिर फ़ॉइल में लपेटकर फ़्रीज़ किया जा सकता है। पिघलाने के लिए, रात भर फ्रिज में रखें और ऊपर बताए अनुसार 30-35 मिनट बेक करें।"],[TP,"मक्खन को सीधे फ्रिज से निकालकर कद्दूकस करके देखें। यह कुछ ही पलों में एकदम सही क्रम्ब्स बनाने का एक तेज़ और आसान तरीका है!"]],
[]))
R.append((3502648,"बोर्श","पारंपरिक पूर्वी यूरोपीय रेसिपी का कम पोटैशियम वाला रूप।","4",None,
["400g चुकंदर, छिला और कटा हुआ","300g गाजर, छिली और गोल टुकड़ों में कटी हुई","2 लहसुन की कलियाँ, बारीक कटी और छिली हुई","90g शैलट (छोटे प्याज़), बारीक कटे हुए","1 तेज पत्ता","1 छोटा चम्मच धनिया के बीज","3 लौंग","एक चुटकी से ½ छोटा चम्मच तक लाल मिर्च पाउडर (आपको कितना तीखा पसंद है और मिर्च कितनी तीखी है, इस पर निर्भर)","1 बड़ा चम्मच कैस्टर शुगर (बारीक चीनी)","1 बड़ा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","2 छोटे चम्मच रेड वाइन सिरका",["परोसने के लिए","4 ब्रेड रोल"],["परोसने के लिए","1 बड़ा चम्मच जैतून का तेल"],["परोसने के लिए","4 अंडे"],["परोसने के लिए","250g फ़ुल फ़ैट दही"],["परोसने के लिए","ताज़ी सोआ की कुछ टहनियों की पत्तियाँ, कटी हुई, या कुछ कटे हुए चाइव्स"]],
["एक मध्यम बर्तन में पानी उबालें और कटा हुआ चुकंदर, गाजर और अंडे डालें। पाँच मिनट उबालें, फिर पानी निथारें और उबले अंडों को ठंडा होने के लिए एक तरफ़ रख दें। ठंडा होने पर, छिलका उतारें और अंडों को बाद में उपयोग के लिए काट लें। आधे उबले चुकंदर और गाजर को एक बड़े सॉसपैन में डालें।","सॉसपैन में 500ml ठंडा पानी, लहसुन, शैलट, तेज पत्ता, धनिया के बीज, लौंग, लाल मिर्च पाउडर, चीनी, जैतून का तेल और आधा सिरका डालें। ढककर उबालें, फिर मध्यम-धीमी आँच पर कर दें। चुकंदर और गाजर के नरम होने तक 20 मिनट धीमी आँच पर पकाएँ।","तेज पत्ता निकालें और फिर सूप को ब्लेंडर में प्यूरी करें। इसे बहुत चिकना बनाने के लिए, आप इसे छलनी से एक बड़े कटोरे या जग में छान सकते हैं, लेकिन यह आवश्यक नहीं हो सकता। चखकर देखें कि क्या इसमें और काली मिर्च या अधिक सिरका मिलाने की ज़रूरत है।","इस व्यंजन को गरम या ठंडा परोसा जा सकता है। यदि गरम परोस रहे हैं, तो सॉसपैन में मध्यम आँच पर दोबारा गरम करें। परोसने से पहले, दही फेंटकर मिलाएँ और कटे हुए सोआ या चाइव्स, थोड़े जैतून के तेल और कटे उबले अंडों से सजाएँ। साथ में एक ब्रेड रोल परोसें।"],
[[CH,"यह एक स्वादिष्ट और सेहतमंद सूप है जिसे गरम या ठंडा परोसा जा सकता है। बनाने के एक-दो दिन बाद खाने पर इसका स्वाद और भी अच्छा होता है।"],[CB,"इस भोजन में ब्रेड रोल कार्बोहाइड्रेट का मुख्य स्रोत हैं। यह मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"इस व्यंजन में पोटैशियम का मुख्य स्रोत चुकंदर है, हालाँकि रेसिपी में उपयोग की गई मात्रा ऐसी सीमा में रखी गई है जो सुनिश्चित करती है कि पूरा भोजन पोटैशियम में कम हो।\nयह व्यंजन फ़ॉस्फ़ेट में कम है, लेकिन इसमें फिर भी कुछ फ़ॉस्फ़ेट होता है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"इस व्यंजन में प्रोटीन कम है, जो इसे उन लोगों के लिए उपयुक्त बनाता है जिन्हें कम प्रोटीन वाला आहार लेने की सलाह दी गई है। इसलिए, यह डायलिसिस पर रहने वालों के लिए उपयुक्त नहीं हो सकता। यदि आपको अधिक प्रोटीन खाने की सलाह दी गई है और आप शाकाहारी/वीगन आहार पर नहीं हैं, तो आप अंडे की जगह 250g पका हुआ कतरा हुआ चिकन ले सकते हैं।"],[GF,"ग्लूटेन-मुक्त ब्रेड रोल के साथ परोसें।"],[VG,"डेयरी-मुक्त योगर्ट या वीगन खट्टी क्रीम का उपयोग करें और अंडों की जगह पानी निथारा हुआ छोलों का एक डिब्बा लें।"],[HO,"यह पहले से ही सेहतमंद व्यंजन है लेकिन आप वसा की मात्रा कम रखने के लिए कम वसा वाला योगर्ट और फ़ाइबर बढ़ाने के लिए साबुत गेहूँ का रोल उपयोग कर सकते हैं।"],[ST,"बोर्श को फ्रिज में तीन दिन तक या फ़्रीज़र में तीन महीने तक (योगर्ट डालने से पहले) रखा जा सकता है।"],["तरल पदार्थ का प्रबंधन","यदि आपको तरल पदार्थों पर प्रतिबंध का पालन करने की सलाह दी गई है, तो इस सूप को अपने दैनिक तरल पदार्थ की अनुमत मात्रा में गिनना याद रखें।"]],
[]))
R.append((3511962,"बनाना ब्रेड","केवल एक केले का उपयोग करने वाली यह रेसिपी स्वादिष्ट व्यंजन या मिठाई के रूप में आनंद लेने के लिए एक स्वादिष्ट कम पोटैशियम और कम नमक वाला विकल्प है।","10",None,
["1 पका केला (छिलके के बिना लगभग 120g)","1 अंडा","½ छोटा चम्मच वनीला एक्सट्रैक्ट","100g बिना नमक का मक्खन, मुलायम किया हुआ","60g हल्की मुलायम ब्राउन शुगर","120g ग्लूटेन-मुक्त सादा मैदा","1 छोटा चम्मच बाइकार्बोनेट ऑफ़ सोडा (बेकिंग सोडा)","1 छोटा चम्मच क्रीम ऑफ़ टार्टर","60g सूखे क्रैनबेरी"],
["ओवन को 190°C/ गैस मार्क 5 पर पहले से गरम करें। 450g के लोफ़ टिन में चिकनाई लगाएँ और कागज़ बिछाएँ।","अंडे को फेंटें और केले तथा वनीला एक्सट्रैक्ट के साथ मसलकर मिलाएँ।","एक अलग कटोरे में मक्खन और चीनी को क्रीम की तरह फेंटें।","केले के मिश्रण को फेंटी हुई चीनी में डालें और एक साथ फेंटें।","मैदा, बेकिंग सोडा, क्रीम ऑफ़ टार्टर और क्रैनबेरी मिलाएँ और अच्छी तरह चलाएँ।","तैयार बेकिंग टिन में डालें और 40-45 मिनट या सींक साफ़ निकलने तक बेक करें। इसे वायर ट्रे पर पूरी तरह ठंडा करने के लिए निकालने से पहले पाँच मिनट टिन में ही ठंडा होने दें।"],
[[CH,"बनाना ब्रेड एक सरल, सुकून देने वाला विकल्प है। यह फ़्रीज़र-अनुकूल संस्करण ग्लूटेन-मुक्त भी है।"],[CB,"इस रेसिपी में कार्बोहाइड्रेट के मुख्य स्रोत मैदा, चीनी, केला और क्रैनबेरी हैं। कार्बोहाइड्रेट के मान उन लोगों के लिए दिए गए हैं जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"केला उच्च पोटैशियम वाला फल है, हालाँकि 10 परोसों के लिए केवल 1 केले का उपयोग किया जा रहा है जो इस रेसिपी को कुल मिलाकर कम पोटैशियम वाला रखता है। इसलिए, एक परोसे का आनंद कम पोटैशियम वाले आहार के हिस्से के रूप में कभी-कभार के व्यंजन के रूप में लिया जा सकता है।\nइस रेसिपी में फ़ॉस्फ़ेट होता है जो मुख्य रूप से फुलाने वाले पदार्थों से आता है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"यह बनाना ब्रेड प्रोटीन में कम है और कम प्रोटीन वाले आहार के हिस्से के रूप में विशेष अवसरों पर इसका आनंद लिया जा सकता है।"],[HO,"इस रेसिपी में चीनी पहले ही घटा दी गई है, हालाँकि यदि आपको यह बहुत मीठी लगे तो आप इसे और घटाने पर विचार कर सकते हैं। आप बिना नमक के मक्खन की जगह कम वसा वाले स्प्रेड का भी उपयोग करना चाह सकते हैं, जिससे वसा की मात्रा घटेगी।"],[CO,"यह रेसिपी अपेक्षाकृत सस्ती है, लेकिन आप मुलायम ब्राउन शुगर की जगह सामान्य कैस्टर शुगर का उपयोग करने पर विचार कर सकते हैं क्योंकि इससे थोड़े पैसे बच सकते हैं।"],[ST,"ठंडा होने के बाद, बनाना ब्रेड को 10 हिस्सों में काटकर हवाबंद डिब्बे में 3 दिन तक रखना सबसे अच्छा है। यदि आप दोस्तों और परिवार के साथ साझा नहीं कर रहे हैं, तो आप अलग-अलग स्लाइस को लपेटकर 3 महीने तक फ़्रीज़ कर सकते हैं। खाने से पहले अच्छी तरह पिघलने दें।"]],
[]))
R.append((3560541,"ब्री और क्रैनबेरी पार्सल","यह कम पोटैशियम वाला नाश्ता त्योहारों के लिए एक अच्छा व्यंजन बनाता है।","18",None,
["12 शीट तैयार बेली हुई फ़ाइलो पेस्ट्री 100g बिना नमक का मक्खन 250g ब्री 75g क्रैनबेरी सॉस 50g कटे हुए अखरोट थोड़े खसखस के बीज (वैकल्पिक)"],
["ओवन को 220°C/ गैस मार्क 7 पर गरम करें। मक्खन पिघलाएँ और उसे फ़ाइलो की हर शीट पर लगाएँ और फिर फ़ाइलो की दो शीट को एक के ऊपर एक रखें, चौड़े किनारे अपनी ओर रखते हुए।","ब्री को 18 मोटी उँगलियों जैसे टुकड़ों में काटें और उन्हें फ़ाइलो शीट के निचले हिस्से पर दूरी रखकर सजाएँ। हर टुकड़े पर 1 छोटा चम्मच क्रैनबेरी सॉस डालें और फिर कुछ कटे हुए अखरोट छिड़कें। फ़ाइलो पेस्ट्री को लंबी पट्टियों में काटें।","फ़ाइलो पेस्ट्री को नीचे से लपेटें। हर रोल को तीन पार्सलों में काटें और हर पार्सल के सिरों को बंद करने के लिए मरोड़ें। पार्सलों पर और मक्खन लगाएँ और खसखस छिड़कें।","सभी सामग्री उपयोग होने तक चरण 2–4 दोहराएँ। ओवन में 10 मिनट बेक करें। भूरा होने पर, ओवन से निकालें और परोसने से पहले थोड़ा ठंडा होने दें।"],
[[CH,"ये स्वादिष्ट फ़ाइलो पेस्ट्री पार्सल एक परिष्कृत व्यंजन बनाते हैं। मलाईदार ब्री, मीठे क्रैनबेरी और अखरोट के कुरकुरेपन से भरे हुए।"],[CB,"इस नाश्ते में फ़ाइलो पेस्ट्री और क्रैनबेरी सॉस कार्बोहाइड्रेट के मुख्य स्रोत हैं। कार्बोहाइड्रेट मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"इस रेसिपी की सामग्री पोटैशियम में कम हैं। यह एक ऐसा नाश्ता है जिसका आनंद कम पोटैशियम वाले आहार के हिस्से के रूप में, किसी विशेष अवसर पर, थोड़ी मात्रा में लिया जा सकता है। इस रेसिपी में फ़ॉस्फ़ेट मुख्य रूप से ब्री से और थोड़ा अखरोट से आता है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस नाश्ते के साथ लेना सुनिश्चित करें और बहुत अधिक खाने से बचें।"],[PR,"इस रेसिपी में प्रोटीन चीज़ और अखरोट से मिलता है।"],[GF,"ग्लूटेन-मुक्त फ़ाइलो पेस्ट्री का उपयोग करें।"],[VT,"जाँच लें कि आपके द्वारा उपयोग किया जा रहा चीज़ शाकाहारी हो।"],[VG,"वीगन पेस्ट्री और उपयुक्त वीगन चीज़ का उपयोग करें।"],[HO,"यह नाश्ता विशेष अवसरों के लिए है और क्रिसमस के समय विशेष रूप से अच्छा रहेगा, हालाँकि इसे केवल सीमित मात्रा में खाना चाहिए। छोटे समारोहों या परिवारों के लिए पूरी रेसिपी को आधा करना भी उचित हो सकता है।"],[CO,"इस रेसिपी की सामग्री अपेक्षाकृत सस्ती हैं, हालाँकि लागत कम करने और स्वाद बनाए रखने के लिए आप अखरोट और/या खसखस छोड़ सकते हैं।"],[ST,"इन्हें ताज़ा पकाकर खाना सबसे अच्छा है, हालाँकि यदि रखना हो, तो उन्हें ठंडा होने दें, हवाबंद डिब्बे में रखें और 3 दिन तक फ्रिज में रखें।"]],
[]))
R.append((3562881,"ब्लैक बीन टैकोज़","ये मैक्सिकन-प्रेरित टैकोज़ फ़ाइबर में उच्च और बहुत पेट भरने वाले हैं। यह सेहतमंद व्यंजन फ़ॉस्फ़ेट, पोटैशियम और नमक में कम है।","4",None,
["1 लाल प्याज़, पतली पट्टियों में कटा हुआ","1 लाल शिमला मिर्च, पतली पट्टियों में कटी हुई","2 बड़े चम्मच जैतून का तेल","200g पानी में डिब्बाबंद स्वीटकॉर्न","½ छोटा चम्मच स्मोक्ड पैपरिका","400g पानी में डिब्बाबंद काली फलियाँ (ब्लैक बीन्स)","2 लहसुन की कलियाँ, कद्दूकस की हुई","½ छोटा चम्मच पिसी दालचीनी","½ छोटा चम्मच पिसा जीरा","काली मिर्च","50g चेरी टमाटर, चार भागों में कटे हुए","1 हरा प्याज़, पतला कटा हुआ","5g ताज़ा धनिया, कटा हुआ","¼ छोटा चम्मच तीखी मिर्च की सॉस","2 नीबू","1 छोटा पका एवोकाडो","8 मिनी टॉर्टिला रैप","1 ताज़ी मिर्च, पतली कटी हुई (वैकल्पिक)"],
["ओवन को 180°C/ 160°C फ़ैन / गैस मार्क 3 पर पहले से गरम करें और दो बेकिंग ट्रे पर ग्रीसप्रूफ़ पेपर बिछाएँ। कटे हुए प्याज़ और लाल शिमला मिर्च को कटोरे में डालें। एक बड़ा चम्मच तेल डालें, काली मिर्च से स्वाद दें और मिलाएँ। सब्ज़ियों को एक ट्रे पर फैलाएँ।","स्वीटकॉर्न का पानी निथारें और उसे थपथपाकर सुखा लें। इसे कटोरे में डालें, काली मिर्च और स्मोक्ड पैपरिका से स्वाद दें और मिलाएँ। स्वीटकॉर्न को दूसरी बेकिंग ट्रे पर फैलाएँ। दोनों ट्रे को 25-30 मिनट के लिए ओवन में रखें, बीच में एक बार चलाएँ, फिर ठंडा होने दें।","फलियों का पानी निथारें और धोएँ, कटोरे में डालें और काँटे से मसल लें। एक सॉसपैन में मध्यम आँच पर तेल गरम करें और लहसुन डालें। 30 सेकंड चलाएँ, फिर दालचीनी, जीरा, काली मिर्च, काली फलियाँ और ज़रूरत हो तो थोड़ा पानी डालें।","तीन मिनट धीरे-धीरे पकाएँ, फिर आँच से उतारें। सालसा के लिए, एक कटोरे में मिर्च की सॉस डालें और ½ नीबू का रस निचोड़कर मिलाएँ। टमाटर, हरे प्याज़ और धनिया की पत्तियाँ डालें और फिर मिलाएँ।","ग्वाकामोले के लिए, एवोकाडो को आधा काटें और गुठली को सावधानी से निकालें। एवोकाडो का सारा गूदा दूसरे कटोरे में निकालें, एक नीबू का रस निचोड़ें और काँटे से मलाईदार बनावट तक मसलें। परोसने तक एक तरफ़ रख दें।","टॉर्टिला रैप फैलाएँ। हर एक पर काली फलियों, सब्ज़ियों और मक्के की परत लगाएँ और थोड़ा सालसा और ग्वाकामोले डालें। प्रति व्यक्ति दो टैकोज़ नीबू की एक फाँक के साथ परोसें (और चाहें तो मिर्च और अतिरिक्त कटा धनिया)।"],
[[CH,"भुनी हुई सब्ज़ियों, काली फलियों और किडनी-अनुकूल सालसा और ग्वाकामोले के साथ, ये टैकोज़ एक झटपट वीगन दोपहर या रात का भोजन बनाते हैं।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट का मुख्य स्रोत टॉर्टिला रैप हैं। इस व्यंजन का कार्बोहाइड्रेट मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"चेरी टमाटर और एवोकाडो जैसी कुछ उच्च पोटैशियम वाली सामग्री के उपयोग के बावजूद, यदि आप इस रेसिपी में बताई गई मात्रा और परोसे के आकार का पालन करते हैं, तो यह व्यंजन कुल मिलाकर पोटैशियम में कम है। काली फलियों में फ़ॉस्फ़ेट होता है लेकिन इस रेसिपी में उपयोग की गई मात्रा कुल फ़ॉस्फ़ेट को कम रखती है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"यह रेसिपी प्रोटीन में कम है, जो इसे उन लोगों के लिए उपयुक्त भोजन बनाती है जिन्हें कम प्रोटीन वाला आहार लेने की सलाह दी गई है।"],[GF,"ग्लूटेन-मुक्त टॉर्टिला रैप का उपयोग करें।"],[HO,"यह सेहतमंद व्यंजन है क्योंकि यह स्वाभाविक रूप से नमक, वसा और चीनी में कम और फ़ाइबर में उच्च है। हालाँकि, टॉर्टिला रैप खरीदते समय लेबल जाँचना और सबसे कम नमक वाले चुनना सबसे अच्छा है।"],[CO,"यह अपेक्षाकृत सस्ता व्यंजन है। हालाँकि, खाने की बर्बादी से बचने के लिए आप बोतलबंद नीबू का रस खरीदना चाह सकते हैं।"],[ST,"इस व्यंजन के सभी हिस्से पहले से तैयार किए जा सकते हैं। सब्ज़ियों, काली फलियों, सालसा और ग्वाकामोले को अलग-अलग हवाबंद डिब्बों में रखें, फ्रिज में रखें और 3 दिन के भीतर उपयोग करें। परोसने से ठीक पहले टैकोज़ जोड़ें।"]],
[]))
